<script setup>
import { computed, onMounted, ref } from 'vue'
import UniversalAdminForm from '../components/admin/UniversalAdminForm.vue'
import BackupRestorePanel from '../components/admin/BackupRestorePanel.vue'
import { ADMIN_FORM_DEFINITIONS } from '../application/admin/adminFormDefinitions.js'
import { AdminService } from '../application/admin/adminService.js'
import { BackupService } from '../application/backup/backupService.js'

const groups=[
 {key:'businessSetup',title:'Business Setup',icon:'◉',forms:['vehicle','driver'],description:'Core vehicle and driver master data.'},
 {key:'vehicleRecords',title:'Vehicle Records',icon:'▣',forms:['compliance','maintenance'],description:'Vehicle compliance and maintenance records.'},
 {key:'finance',title:'Finance',icon:'₹',forms:['loan','loanPayment','prepayment'],description:'Loans and actual financing movements.'},
 {key:'planningControls',title:'Planning & Controls',icon:'⌁',forms:['driverTarget','breakEvenInputs'],description:'Effective-dated targets and break-even inputs.'}
]
const settingsMenu=[
 {key:'backup',title:'Backup & Restore',subtitle:'Protect and recover complete KFE data',icon:'↥'},
 {key:'application',title:'Application Settings',subtitle:'Application-level preferences and controls',icon:'⚙'},
 {key:'reset',title:'Data Reset',subtitle:'Clear the canonical KFE dataset',icon:'⚠'}
]
const adminSection=ref('records'),selected=ref('vehicle'),settingsSelected=ref('backup')
const records=ref([]),editing=ref(null),draft=ref({}),formOpen=ref(false),loading=ref(false),error=ref(''),notice=ref('')
const all=ref({vehicle:[],driver:[],loan:[]})
const currentGroup=computed(()=>groups.find(g=>g.forms.includes(selected.value))||groups[0])
const baseDefinition=computed(()=>ADMIN_FORM_DEFINITIONS[selected.value])
const activeDefinition=computed(()=>{const d=structuredClone(baseDefinition.value);for(const f of d.fields){if(f.key==='vehicleId')f.options=all.value.vehicle.map(x=>x.id);if(f.key==='driverId')f.options=all.value.driver.map(x=>x.id);if(f.key==='loanId')f.options=all.value.loan.map(x=>x.id)}return d})
function label(key,record){const v=record.values||record;if(key==='vehicle')return [v.registrationNumber,v.make,v.model].filter(Boolean).join(' · ')||record.id;if(key==='driver')return v.name||record.id;if(key==='loan')return [v.lender,v.accountReference].filter(Boolean).join(' · ')||record.id;return record.id}
function display(value){for(const k of ['vehicle','driver','loan']){const found=all.value[k].find(x=>x.id===value);if(found)return label(k,found)}return value}
async function load(){loading.value=true;error.value='';try{records.value=await AdminService.list(selected.value);for(const k of Object.keys(all.value))all.value[k]=await AdminService.list(k)}catch(e){error.value=e.message||'Unable to load records.'}finally{loading.value=false}}
function choose(key){selected.value=key;editing.value=null;draft.value={};formOpen.value=false;notice.value='';load()}
function chooseGroup(group){choose(group.forms[0])}
function openRecords(){adminSection.value='records';error.value='';notice.value=''}
function openSettings(){adminSection.value='settings';formOpen.value=false;editing.value=null;draft.value={};error.value='';notice.value=''}
function chooseSetting(key){settingsSelected.value=key;error.value='';notice.value=''}
function add(){editing.value=null;draft.value={};formOpen.value=true}
function edit(record){editing.value=record.id;draft.value=structuredClone(record.values||{});formOpen.value=true}
async function save(values){loading.value=true;error.value='';notice.value='';try{const id=editing.value;await AdminService.save(selected.value,values,id);notice.value=id!==null?'Record updated successfully.':'Record created successfully.';editing.value=null;draft.value={};formOpen.value=false;await load()}catch(e){error.value=e.validation?Object.values(e.validation).join(' '):e.message||'Save failed.'}finally{loading.value=false}}
async function remove(record){if(!confirm('Delete this source record? Related records may prevent deletion.'))return;loading.value=true;error.value='';try{await AdminService.remove(selected.value,record.id);notice.value='Record deleted.';await load()}catch(e){error.value=e.message||'Delete failed.'}finally{loading.value=false}}
async function resetData(){if(!confirm('Reset all KFE data? Create a backup first if you may need the current data.'))return;if(!confirm('Final confirmation: permanently delete all current KFE records?'))return;loading.value=true;error.value='';notice.value='';try{await BackupService.resetData();notice.value='All canonical KFE data has been reset.'}catch(e){error.value=e.message||'Data reset failed.'}finally{loading.value=false}}
onMounted(load)
</script>

<template>
<section class="admin-page" aria-label="Admin">
<header class="admin-head"><div><div class="eyebrow">ADMIN · MASTER CONTROL</div><h1>Admin</h1><p>Enter and manage the business facts that belong here. Work owns shifts, Timeline owns ride corrections, and Fuel owns refuelling.</p></div><div class="authority"><span>●</span> One entry point per business fact</div></header>
<nav class="admin-nav" aria-label="Admin sections"><button :class="{active:adminSection==='records'}" @click="openRecords"><span>▦</span><strong>Business records</strong></button><button :class="{active:adminSection==='settings'}" @click="openSettings"><span>⚙</span><strong>Settings &amp; Data</strong></button></nav>
<template v-if="adminSection==='records'">
<section class="flow" aria-label="Admin information architecture"><div class="flow-heading"><div><div class="section-label">BUSINESS CONTROL FLOW</div><h2>Manage the business in this order</h2><p>Set up the business first, then maintain vehicle records, finance and planning controls.</p></div><span class="flow-rule">One fact · one owner</span></div><div class="flow-grid"><button v-for="(group,index) in groups" :key="group.key" class="flow-card" :class="{active:currentGroup.key===group.key}" @click="chooseGroup(group)"><span class="flow-step">{{index+1}}</span><span class="flow-icon">{{group.icon}}</span><span><strong>{{group.title}}</strong><small>{{group.description}}</small><i v-for="key in group.forms" :key="key">{{ADMIN_FORM_DEFINITIONS[key].title}}</i></span></button></div></section>
<section class="workspace"><div class="workspace-head"><div><div class="section-label">{{currentGroup.title}}</div><h2>{{baseDefinition.title}}</h2><p>{{currentGroup.description}}</p></div><button class="primary" @click="add">＋ New {{baseDefinition.title}}</button></div>
<nav class="record-tabs" :aria-label="currentGroup.title"><button v-for="key in currentGroup.forms" :key="key" :class="{active:selected===key}" @click="choose(key)">{{ADMIN_FORM_DEFINITIONS[key].title}}</button></nav>
<p v-if="error" class="message error">{{error}}</p><p v-if="notice" class="message notice">✓ {{notice}}</p>
<UniversalAdminForm v-if="formOpen" :definition="activeDefinition" :model-value="draft" @update:model-value="draft=$event" @submit="save" @cancel="formOpen=false;editing=null;draft={}" :submit-label="editing!==null?'Update record':'Save record'" />
<div v-else-if="loading" class="empty"><span class="spinner"></span><strong>Loading records…</strong></div>
<div v-else-if="records.length" class="record-list"><article v-for="record in records" :key="record.id" class="record"><div><div class="record-title"><strong>{{label(selected,record)}}</strong><span>Authoritative source</span></div><small>Updated {{record.updatedAt||'—'}}</small><div class="chips"><span v-for="(value,key) in record.values" v-if="value!==''&&value!==null&&value!==undefined&&key!=='notes'" :key="key">{{display(value)}}</span></div></div><div class="actions"><button @click="edit(record)">Edit</button><button class="delete" @click="remove(record)">Delete</button></div></article></div>
<div v-else class="empty"><div class="empty-icon">＋</div><strong>No {{baseDefinition.title}} records yet</strong><span>Create the first authoritative source record for this section.</span><button class="primary" @click="add">Create {{baseDefinition.title}}</button></div></section>
</template>
<template v-else>
<section class="settings-layout"><aside class="settings-menu"><div class="section-label">SETTINGS &amp; DATA</div><h2>Control centre</h2><button v-for="item in settingsMenu" :key="item.key" :class="{active:settingsSelected===item.key}" @click="chooseSetting(item.key)"><span class="settings-icon">{{item.icon}}</span><span><strong>{{item.title}}</strong><small>{{item.subtitle}}</small></span><b>›</b></button></aside>
<section v-if="settingsSelected==='backup'" class="settings-workspace"><div class="settings-heading"><div><div class="section-label">DATA PROTECTION</div><h2>Backup &amp; Restore</h2><p>One managed backup contains the complete recoverable KFE dataset, including settings.</p></div><span class="status">Protected</span></div><BackupRestorePanel /></section>
<section v-else-if="settingsSelected==='application'" class="settings-workspace"><div class="settings-heading"><div><div class="section-label">APPLICATION SETTINGS</div><h2>Application Settings</h2><p>Application-level preferences belong here rather than being mixed into business records.</p></div><span class="status">Settings</span></div><div class="info-card"><strong>Settings travel with backup and restore</strong><p>KFE application settings are part of the canonical backup/restore boundary. Backup/sync provider configuration remains separate from portable business data.</p></div></section>
<section v-else class="settings-workspace"><div class="settings-heading"><div><div class="section-label">DESTRUCTIVE DATA CONTROL</div><h2>Data Reset</h2><p>Permanently clear the canonical KFE dataset. The application itself remains installed.</p></div><span class="status danger">Destructive</span></div><div class="reset-card"><div><h2>Reset all KFE data</h2><p>This clears canonical business records. Local backup copies are not deleted, so a backup can be restored afterward.</p></div><button class="reset-button" :disabled="loading" @click="resetData">Reset all data</button></div><p v-if="error" class="message error">{{error}}</p><p v-if="notice" class="message notice">✓ {{notice}}</p></section></section>
</template>
</section>
</template>

<style scoped>
.admin-page{width:min(100%,1000px);margin:0 auto;padding:22px 15px 36px;box-sizing:border-box;background:var(--kfe-ui-bg,#f5f7fb);color:var(--kfe-ui-text,#101828)}.eyebrow,.section-label{font-size:.62rem;font-weight:900;letter-spacing:.13em;color:var(--kfe-muted-text,#667085)}.admin-head{display:flex;justify-content:space-between;align-items:flex-start;gap:14px;margin-bottom:15px}.admin-head h1{margin:5px 0 4px;font-size:clamp(1.6rem,6vw,2rem);letter-spacing:-.04em}.admin-head p{margin:0;max-width:690px;font-size:.76rem;line-height:1.5;color:var(--kfe-muted-text,#667085)}.authority{padding:8px 11px;border:1px solid var(--kfe-ui-border,#e4e7ec);border-radius:999px;background:var(--kfe-ui-surface,#fff);font-size:.6rem;font-weight:850;white-space:nowrap}.authority span{color:var(--kfe-success,#079455)}.admin-nav{display:grid;grid-template-columns:1fr 1fr;gap:6px;padding:4px;margin-bottom:12px;border:1px solid var(--kfe-ui-border,#e4e7ec);border-radius:14px;background:var(--kfe-ui-surface,#fff)}.admin-nav button{min-height:44px;border:0;border-radius:10px;background:transparent;color:var(--kfe-muted-text,#667085);display:flex;align-items:center;justify-content:center;gap:7px;cursor:pointer}.admin-nav button.active{background:var(--kfe-accent-soft,#eff6ff);color:var(--kfe-ui-accent,#2563eb)}.admin-nav strong{font-size:.67rem}.flow{margin-bottom:11px;padding:14px;border:1px solid var(--kfe-ui-border,#e4e7ec);border-radius:17px;background:var(--kfe-ui-surface,#fff);box-shadow:0 5px 20px rgba(16,24,40,.025)}.flow-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:10px}.flow-heading h2{margin:3px 0;font-size:.9rem;letter-spacing:-.02em}.flow-heading p{margin:3px 0 0;color:var(--kfe-muted-text,#667085);font-size:.6rem;line-height:1.4}.flow-rule{padding:6px 9px;border-radius:999px;background:var(--kfe-accent-soft,#eff6ff);color:var(--kfe-ui-accent,#2563eb);font-size:.53rem;font-weight:850;white-space:nowrap}.flow-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px}.flow-card{position:relative;display:flex;gap:8px;align-items:flex-start;padding:11px;border:1px solid var(--kfe-ui-border,#e4e7ec);border-radius:15px;background:var(--kfe-ui-surface,#fff);cursor:pointer;text-align:left;box-shadow:0 3px 13px rgba(16,24,40,.03)}.flow-card.active{border-color:color-mix(in srgb,var(--kfe-ui-accent,#2563eb) 35%,var(--kfe-ui-border,#e4e7ec));background:var(--kfe-accent-soft,#eff6ff)}.flow-step{position:absolute;top:7px;right:7px;min-width:17px;height:17px;padding:0 4px;box-sizing:border-box;display:grid;place-items:center;border-radius:999px;background:var(--kfe-ui-bg,#f5f7fb);color:var(--kfe-muted-text,#667085);font-size:.48rem;font-weight:900}.flow-icon{width:31px;height:31px;display:grid;place-items:center;flex:0 0 31px;border-radius:9px;background:var(--kfe-ui-bg,#f5f7fb);font-weight:900}.flow-card strong{display:block;font-size:.74rem}.flow-card small{display:block;margin-top:2px;color:var(--kfe-muted-text,#667085);font-size:.6rem;line-height:1.4}.flow-card i{display:inline-block;margin:7px 4px 0 0;padding:3px 6px;border-radius:6px;background:var(--kfe-ui-bg,#f5f7fb);font-style:normal;font-size:.55rem;font-weight:750}.workspace,.settings-menu,.settings-workspace{border:1px solid var(--kfe-ui-border,#e4e7ec);border-radius:17px;background:var(--kfe-ui-surface,#fff);box-shadow:0 5px 20px rgba(16,24,40,.035)}.workspace{padding:15px}.workspace-head,.settings-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}.workspace-head h2,.settings-heading h2,.settings-menu h2{margin:3px 0;font-size:1.08rem;letter-spacing:-.02em}.workspace-head p,.settings-heading p{margin:4px 0 0;color:var(--kfe-muted-text,#667085);font-size:.65rem;line-height:1.45}.primary{min-height:40px;padding:0 11px;border:0;border-radius:10px;background:var(--kfe-ui-accent,#2563eb);color:#fff;font-size:.64rem;font-weight:900;cursor:pointer;white-space:nowrap}.record-tabs{display:flex;gap:6px;overflow-x:auto;margin:12px -2px 5px;padding:0 2px 9px;border-bottom:1px solid var(--kfe-ui-border,#e4e7ec);scrollbar-width:none}.record-tabs button{min-height:35px;padding:0 11px;border:1px solid transparent;border-radius:9px;background:var(--kfe-ui-bg,#f5f7fb);color:var(--kfe-muted-text,#667085);font-size:.6rem;font-weight:800;white-space:nowrap;cursor:pointer}.record-tabs button.active{background:var(--kfe-accent-soft,#eff6ff);color:var(--kfe-ui-accent,#2563eb);border-color:color-mix(in srgb,var(--kfe-ui-accent,#2563eb) 25%,transparent)}.record-list{display:grid;gap:7px}.record{display:flex;justify-content:space-between;gap:12px;padding:12px;border:1px solid var(--kfe-ui-border,#e4e7ec);border-radius:12px}.record-title{display:flex;gap:7px;align-items:center}.record-title strong{font-size:.7rem}.record-title span{font-size:.52rem;padding:3px 6px;border-radius:999px;background:var(--kfe-accent-soft,#eff6ff);color:var(--kfe-ui-accent,#2563eb);font-weight:800}.record small{display:block;margin-top:4px;color:var(--kfe-muted-text,#667085);font-size:.56rem}.chips{display:flex;gap:4px;flex-wrap:wrap;margin-top:7px}.chips span{padding:4px 6px;border-radius:6px;background:var(--kfe-ui-bg,#f5f7fb);font-size:.53rem}.actions{display:flex;gap:5px;align-items:flex-start}.actions button{min-height:31px;padding:0 8px;border:1px solid var(--kfe-ui-border,#e4e7ec);border-radius:8px;background:var(--kfe-ui-surface,#fff);font-size:.58rem;font-weight:800;cursor:pointer}.actions .delete{color:#b42318}.message{margin:9px 0;padding:9px;border-radius:9px;font-size:.62rem}.message.error{background:#fef3f2;color:#b42318}.message.notice{background:#ecfdf3;color:#027a48}.empty{min-height:170px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px;text-align:center;color:var(--kfe-muted-text,#667085)}.empty strong{color:var(--kfe-ui-text,#101828);font-size:.76rem}.empty>span{font-size:.61rem}.empty .primary{margin-top:5px}.empty-icon{width:36px;height:36px;display:grid;place-items:center;border-radius:11px;background:var(--kfe-accent-soft,#eff6ff);color:var(--kfe-ui-accent,#2563eb);font-size:1.1rem}.spinner{width:17px;height:17px;border:2px solid var(--kfe-ui-border,#e4e7ec);border-top-color:var(--kfe-ui-accent,#2563eb);border-radius:50%;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.settings-layout{display:grid;grid-template-columns:270px minmax(0,1fr);gap:11px}.settings-menu{padding:14px}.settings-menu button{width:100%;display:grid;grid-template-columns:29px 1fr 12px;gap:8px;align-items:center;text-align:left;margin-top:7px;padding:9px;border:1px solid transparent;border-radius:10px;background:transparent;color:inherit;cursor:pointer}.settings-menu button.active{background:var(--kfe-accent-soft,#eff6ff);border-color:color-mix(in srgb,var(--kfe-ui-accent,#2563eb) 20%,transparent)}.settings-icon{width:29px;height:29px;display:grid;place-items:center;border-radius:8px;background:var(--kfe-ui-bg,#f5f7fb)}.settings-menu strong{display:block;font-size:.62rem}.settings-menu small{display:block;margin-top:2px;color:var(--kfe-muted-text,#667085);font-size:.53rem;line-height:1.35}.settings-menu b{color:var(--kfe-muted-text,#667085)}.settings-workspace{padding:15px}.status{padding:6px 9px;border-radius:999px;background:var(--kfe-accent-soft,#eff6ff);color:var(--kfe-ui-accent,#2563eb);font-size:.55rem;font-weight:850;white-space:nowrap}.status.danger{background:#fef3f2;color:#b42318}.info-card,.reset-card{margin-top:15px;padding:15px;border:1px solid var(--kfe-ui-border,#e4e7ec);border-radius:13px}.info-card strong{font-size:.7rem}.info-card p,.reset-card p{margin:5px 0 0;color:var(--kfe-muted-text,#667085);font-size:.62rem;line-height:1.5}.reset-card{display:flex;justify-content:space-between;align-items:center;gap:15px}.reset-card h2{margin:0;font-size:.82rem}.reset-button{min-height:39px;padding:0 12px;border:1px solid #fda29b;border-radius:9px;background:#fef3f2;color:#b42318;font-size:.61rem;font-weight:900;cursor:pointer;white-space:nowrap}.reset-button:disabled{opacity:.55;cursor:wait}@media(max-width:850px){.flow-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.admin-head{flex-direction:column}.authority{align-self:flex-start}.flow{grid-template-columns:1fr}.settings-layout{grid-template-columns:1fr}.record{flex-direction:column}.actions{justify-content:flex-end}.workspace-head,.settings-heading,.flow-heading{flex-direction:column}.flow-rule{align-self:flex-start}.primary{align-self:flex-start}.reset-card{flex-direction:column;align-items:flex-start}.reset-button{width:100%}}
</style>
